    {
      "english": "As for this book, I have already read it.",
      "sseynoy": "Ca shuh, soi gé duek yí.",
      "status": "creator_confirmed_2026-11-25",
      "modernized_from_2026_11_20": "",
      "id": "g1125-0",
      "source": "GRAMMAR_2026-11-25.md",
      "row": 1,
      "learner_note": "Front the book as the topic; the rest of the sentence tells what happened to it."
    },
    {
      "english": "I put the book on the table.",
      "sseynoy": "Soi zàang shuh fàng oe zhak sàng.",
      "status": "creator_confirmed_2026-11-25",
      "modernized_from_2026_11_20": "",
      "id": "g1125-1",
      "source": "GRAMMAR_2026-11-25.md",
      "row": 2,
      "learner_note": "zàang places the affected book before fàng in this pattern."
    },
    {
      "english": "I put the book on the table.",
      "sseynoy": "Soi fàng shuh oe zhak sàng.",
      "status": "creator_confirmed_2026-11-25",
      "modernized_from_2026_11_20": "",
      "id": "g1125-2",
      "source": "GRAMMAR_2026-11-25.md",
      "row": 3,
      "learner_note": "The ordinary subject–verb–object order is also natural here."
    },
    {
      "english": "He hates himself.",
      "sseynoy": "Y hòen zỳgí.",
      "status": "creator_confirmed_2026-11-25",
      "modernized_from_2026_11_20": "",
      "id": "g1125-3",
      "source": "GRAMMAR_2026-11-25.md",
      "row": 4,
      "learner_note": "zỳgí refers back to the subject."
    },
    {
      "english": "They love each other.",
      "sseynoy": "Ydáy sang ày.",
      "status": "creator_confirmed_2026-11-25",
      "modernized_from_2026_11_20": "",
      "id": "g1125-4",
      "source": "GRAMMAR_2026-11-25.md",
      "row": 5,
      "learner_note": "sang adds the each-other meaning before ày."
    },
    {
      "english": "I bought this for you.",
      "sseynoy": "Soi vì je máay ca yí.",
      "status": "creator_confirmed_2026-11-25",
      "modernized_from_2026_11_20": "",
      "id": "g1125-5",
      "source": "GRAMMAR_2026-11-25.md",
      "row": 6,
      "learner_note": "Use falling-tone vì before the beneficiary je."
    },
    {
      "english": "If I had known, I wouldn't have gone.",
      "sseynoy": "Rae soi ýzin zhi shé, soi zuk fue xàng.",
      "status": "creator_confirmed_2026-11-25",
      "modernized_from_2026_11_20": "",
      "id": "g1125-6",
      "source": "GRAMMAR_2026-11-25.md",
      "row": 7,
      "learner_note": "rae opens the condition and zuk introduces the result."
    },
    {
      "english": "Apparently, he has already left.",
      "sseynoy": "Mun shet, y gé li yí.",
      "status": "creator_confirmed_2026-11-25",
      "modernized_from_2026_11_20": "",
      "id": "g1125-7",
      "source": "GRAMMAR_2026-11-25.md",
      "row": 8,
      "learner_note": "mun shet presents the statement as something reported."
    },
    {
      "english": "I used to go there every day.",
      "sseynoy": "Soi ýzin máy rit xàng cachúh.",
      "status": "creator_confirmed_2026-11-25",
      "modernized_from_2026_11_20": "",
      "id": "g1125-8",
      "source": "GRAMMAR_2026-11-25.md",
      "row": 9,
      "learner_note": "ýzin sets past reference and máy rit means every day."
    },
    {
      "english": "Have a look.",
      "sseynoy": "Kàn kàn.",
      "status": "creator_confirmed_2026-11-25",
      "modernized_from_2026_11_20": "",
      "id": "g1125-9",
      "source": "GRAMMAR_2026-11-25.md",
      "row": 10,
      "learner_note": "Repeating the verb gives a brief, bounded invitation to look."
    },
    {
      "english": "Look again and again.",
      "sseynoy": "Zàey kàn zàey kàn.",
      "status": "creator_confirmed_2026-11-25",
      "modernized_from_2026_11_20": "",
      "id": "g1125-10",
      "source": "GRAMMAR_2026-11-25.md",
      "row": 11,
      "learner_note": "Repeat zàey kàn for repeated looking."
    },
    {
      "english": "I don't want everyone to come.",
      "sseynoy": "Soi fue yok máy gàa rin lay.",
      "status": "creator_confirmed_2026-11-25",
      "modernized_from_2026_11_20": "",
      "id": "g1125-11",
      "source": "GRAMMAR_2026-11-25.md",
      "row": 12,
      "learner_note": "fue comes before yok, so the wanting is negated."
    },
    {
      "english": "I want everyone not to come.",
      "sseynoy": "Soi yok máy gàa rin fue lay.",
      "status": "creator_confirmed_2026-11-25",
      "modernized_from_2026_11_20": "",
      "id": "g1125-12",
      "source": "GRAMMAR_2026-11-25.md",
      "row": 13,
      "learner_note": "fue comes inside the complement, so the coming is negated."
    }
